          break;
        default:
          providersBuilder.put(
              key, invalidIdentifierCharacters.replaceFrom(key.toString(), '_') + "Provider");
          break;
      }
    }
    this.providerNames = providersBuilder.build();
  }

  String name() {
    return name;
  }

  String extendingType() {
    return extendingType;
  }

  ImmutableSortedSet<String> implementingTypes() {
    return implementingTypes;
  }

  boolean publicType() {
    return publicType;
